namespace VidnoeDecor {
public static class AutumnQuarter {
 const string F="Assets/Environment/VidnoeDecor";
 static Terrain terrain;static GameObject root;static Material grass,leafFloor,path,blue,green,rust,wood,red,yellow,steel,white;static System.Random rng;static List<Bounds> buildings;static List<(Vector3 p,float radius)> roadPoints;static Dictionary<string,Material> autumn=new();static int meshId;
 static float Y(float x,float z)=>terrain.SampleHeight(new Vector3(x,0,z))+terrain.transform.position.y;
 static Vector3 Ground(float x,float z,float offset=0)=>new(x,Y(x,z)+offset,z);
 static GameObject Group(string name,Transform parent=null){var g=new GameObject(name);g.transform.SetParent(parent?parent:root.transform,false);return g;}
 static float R(float lo,float hi)=>(float)(lo+rng.NextDouble()*(hi-lo));
 static Material Mat(string name,Color c,string texture=null){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name,color=c};m.SetFloat("_Smoothness",.08f);if(texture!=null)m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(texture));AssetDatabase.CreateAsset(m,F+"/Materials/"+name+".mat");return m;}
 static bool Rect(float x,float z,float a,float b,float c,float d)=>x>a&&x<b&&z>c&&z<d;
 static bool Walk(float x,float z)=>Rect(x,z,970,974,1460,1518)||Rect(x,z,880,1003,1503,1506)||Rect(x,z,885,906,1477,1479)||Rect(x,z,974,1007,1464,1467);
 static bool Free(float x,float z,float margin=0){foreach(var b in buildings)if(x>b.min.x-margin&&x<b.max.x+margin&&z>b.min.z-margin&&z<b.max.z+margin)return false;foreach(var q in roadPoints){float dx=x-q.p.x,dz=z-q.p.z;if(Mathf.Abs(dx)<q.radius+margin&&Mathf.Abs(dz)<q.radius+margin&&dx*dx+dz*dz<(q.radius+margin)*(q.radius+margin))return false;}return true;}
 static bool Special(float x,float z)=>Rect(x,z,975,1002,1471,1501)||Rect(x,z,886,905,1480,1500);
 static GameObject Surface(string name,float x0,float x1,float z0,float z1,Material mat,bool mask,float step=1,float lift=.045f){var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();int nx=Mathf.CeilToInt((x1-x0)/step),nz=Mathf.CeilToInt((z1-z0)/step);for(int iz=0;iz<nz;iz++)for(int ix=0;ix<nx;ix++){float xa=Mathf.Lerp(x0,x1,(float)ix/nx),xb=Mathf.Lerp(x0,x1,(float)(ix+1)/nx),za=Mathf.Lerp(z0,z1,(float)iz/nz),zb=Mathf.Lerp(z0,z1,(float)(iz+1)/nz);if(mask&&new[]{new Vector2(xa,za),new Vector2(xa,zb),new Vector2(xb,za),new Vector2(xb,zb)}.Any(p=>!Free(p.x,p.y,.55f)||Walk(p.x,p.y)||Special(p.x,p.y)))continue;int i=v.Count;foreach(var p in new[]{Ground(xa,za,lift),Ground(xa,zb,lift),Ground(xb,zb,lift),Ground(xb,za,lift)}){v.Add(p);uv.Add(new Vector2(p.x/3,p.z/3));}tri.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}return MeshObject(name,v,tri,uv,mat);}
 static GameObject MeshObject(string name,List<Vector3> vertices,List<int> triangles,List<Vector2> uvs,Material mat){var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.SetUVs(0,uvs);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,F+"/Meshes/"+(meshId++).ToString("D3")+"_"+name+".asset");var go=Group(name);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 static GameObject Box(string name,Transform parent,Vector3 local,Vector3 size,Material mat,bool collider=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=local;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Bar(string name,Transform parent,Vector3 a,Vector3 b,float thickness,Material mat){var g=Box(name,parent,(a+b)/2,new Vector3(thickness,(b-a).magnitude,thickness),mat,false);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static void Combine(GameObject g,Material mat,string name){var filters=g.GetComponentsInChildren<MeshFilter>();var ci=filters.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=g.transform.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(ci);AssetDatabase.CreateAsset(mesh,F+"/Meshes/"+(meshId++).ToString("D3")+"_"+name+".asset");foreach(var child in g.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 public static void Build(){
  var scene=EditorSceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/SampleScene_TerrainRoads.unity"||scene.isDirty)throw new Exception("Open saved target scene first.");if(GameObject.Find("Vidnoe — Autumn Abandoned Courtyard"))throw new Exception("Decoration already exists; edit existing objects.");
  rng=new System.Random(7624);terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>();var net=UnityEngine.Object.FindFirstObjectByType<TerrainRoads.TerrainRoadNetwork>();
  buildings=new();foreach(var g in scene.GetRootGameObjects().Where(g=>g.name.StartsWith("Building_Shk_")&&g.name.EndsWith("FINISH"))){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var rr in rs)b.Encapsulate(rr.bounds);buildings.Add(b);}foreach(var rr in GameObject.Find("EmptyBuildings").GetComponentsInChildren<Renderer>())buildings.Add(rr.bounds);
  roadPoints=new();foreach(var link in net.links){var r=link.road;int n=Mathf.CeilToInt(r.route.CalculateLength());for(int i=0;i<=n;i++)roadPoints.Add(((Vector3)r.route.EvaluatePosition((float)i/n),r.width*.5f+.5f));}
  root=new GameObject("Vidnoe — Autumn Abandoned Courtyard");Undo.RegisterCreatedObjectUndo(root,"Осеннее наполнение квартала");
  grass=Mat("Autumn sparse ground",new Color(.73f,.73f,.57f),"Assets/ADG_Textures/ground_vol1/ground4/ground4_Diffuse.tga");leafFloor=Mat("Fallen leaf litter",new Color(.66f,.55f,.30f),"Assets/ADG_Textures/ground_vol1/ground9/ground9_Diffuse.tga");path=Mat("Worn footpath",new Color(.65f,.62f,.53f),"Assets/Environment/KursHub/Textures/FloorConcrete_BaseColor.png");blue=Mat("Weathered blue fence",new Color(.12f,.35f,.65f),"Assets/Environment/KursHub/Textures/BluePaint_BaseColor.png");green=Mat("Faded green rails",new Color(.22f,.40f,.25f));rust=Mat("Rust",new Color(.31f,.19f,.12f),"Assets/Environment/KursHub/Textures/RustedSteel_BaseColor.png");wood=Mat("Worn timber",new Color(.45f,.39f,.25f),"Assets/Environment/KursHub/Textures/WornWood_BaseColor.png");red=Mat("Faded red roof",new Color(.45f,.14f,.10f));yellow=Mat("Faded yellow",new Color(.66f,.49f,.12f));steel=Mat("Dull metal",new Color(.29f,.31f,.30f));white=Mat("Court faded lines",new Color(.64f,.65f,.55f));
  Surface("Autumn ground islands",838,1048,1420,1536,grass,true,1.2f);
  Surface("Main pedestrian path",970,974,1461,1517,path,false,.6f,.06f);Surface("Rear pedestrian link",883,1003,1503,1506,path,false,.6f,.06f);Surface("Playground access",885,905,1477,1479,path,false,.6f,.06f);Surface("Court access",974,1005,1464,1467,path,false,.6f,.06f);
  Court();Playground();
  var treeGroup=Group("Autumn trees — prefab instances");int count=0;var positions=new List<Vector3>();
  for(float z=1424;z<1532;z+=7.8f)for(float x=842;x<1044;x+=7.5f){float xx=x+R(-2,2),zz=z+R(-2,2);if(!Free(xx,zz,3.8f)||Walk(xx,zz)||Special(xx,zz))continue;if(positions.Any(p=>Vector2.Distance(new(p.x,p.z),new(xx,zz))<5))continue;string species=new[]{"Linden","Maple","Birch","Aspen"}[rng.Next(4)];string variant=rng.NextDouble()<.55?"Weathered":"Young";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>($"Assets/Props/MoscowTrees/Prefabs/{species}_{variant}.prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);g.transform.SetParent(treeGroup.transform);g.name=$"Autumn {species} {++count:D3}";g.transform.position=Ground(xx,zz,-.04f);g.transform.rotation=Quaternion.Euler(0,R(0,360),0);g.transform.localScale=Vector3.one*R(.85f,1.25f);var so=new SerializedObject(g.GetComponent<MoscowTreeWind>());so.FindProperty("variationSeed").intValue=rng.Next(10000);so.FindProperty("windStrength").floatValue=.35f;so.ApplyModifiedPropertiesWithoutUndo();foreach(var rr in g.GetComponentsInChildren<Renderer>(true)){if(!rr.name.Contains("Leaves"))continue;var mats=rr.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i]&&mats[i].name.Contains("Leaves"))mats[i]=Autumn(mats[i]);rr.sharedMaterials=mats;if(rng.NextDouble()<.35)rr.enabled=false;}positions.Add(g.transform.position);}
  foreach(var p in positions){float radius=R(1.4f,2.6f);if(Free(p.x,p.z,radius))Surface("Leaf litter "+meshId,p.x-radius,p.x+radius,p.z-radius,p.z+radius,leafFloor,false,1,.065f);}
  Furniture();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("work/VidnoeDecor/result.txt",$"Trees: {count}; root: {root.name}; source terrain unchanged; autumn recolour in independent materials.");Selection.activeGameObject=root;
 }
 static Material Autumn(Material source){if(autumn.TryGetValue(source.name,out var existing))return existing;var m=new Material(source){name=source.name+"_Autumn"};var tex=source.GetTexture("_BaseMap") as Texture2D;if(tex){var rt=RenderTexture.GetTemporary(tex.width,tex.height,0);Graphics.Blit(tex,rt);var previous=RenderTexture.active;RenderTexture.active=rt;var copy=new Texture2D(tex.width,tex.height,TextureFormat.RGBA32,false);copy.ReadPixels(new Rect(0,0,tex.width,tex.height),0,0);var pixels=copy.GetPixels();for(int i=0;i<pixels.Length;i++){var p=pixels[i];Color.RGBToHSV(p,out float h,out float s,out float v);var q=Color.HSVToRGB(.115f,.68f,Mathf.Clamp(v*1.12f,.13f,.94f));q.a=p.a;pixels[i]=q;}copy.SetPixels(pixels);copy.Apply();string file=F+"/Materials/"+m.name+".png";File.WriteAllBytes(file,copy.EncodeToPNG());RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(copy);AssetDatabase.ImportAsset(file);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(file));m.SetColor("_BaseColor",Color.white);}AssetDatabase.CreateAsset(m,F+"/Materials/"+m.name+".mat");autumn.Add(source.name,m);return m;}
 static void Court(){
  var court=Group("Blue fenced sports court — gate south");Surface("Worn sports surface",977,1000,1471,1500,Mat("Old green court",new Color(.21f,.30f,.23f),"Assets/Environment/KursHub/Textures/FloorConcrete_BaseColor.png"),false,.6f,.09f);
  var frame=Group("High blue fence mesh",court.transform);float x0=977,x1=1000,z0=1471,z1=1500;
  FenceSide(frame.transform,new(x0,0,z0),new(x0,0,z1),false);FenceSide(frame.transform,new(x1,0,z0),new(x1,0,z1),false);FenceSide(frame.transform,new(x0,0,z1),new(x1,0,z1),false);FenceSide(frame.transform,new(x0,0,z0),new(x1,0,z0),true);Combine(frame,blue,"BlueFence");
  foreach(float z in new[]{1474f,1497f}){var hoop=Group("Basketball structure",court.transform);hoop.transform.position=Ground(988.5f,z);Box("Support",hoop.transform,new(0,1.65f,0),new(.14f,3.3f,.14f),blue);Box("Backboard",hoop.transform,new(0,3.05f,z<1480?.6f:-.6f),new(1.8f,1.05f,.08f),white);Box("Rim",hoop.transform,new(0,2.85f,z<1480?1:-1),new(.55f,.035f,.5f),rust,false);}
  Surface("Centre line",977.7f,999.3f,1485.43f,1485.5f,white,false,.8f,.105f);
 }
 static void FenceSide(Transform parent,Vector3 a,Vector3 b,bool gate){float length=Vector3.Distance(a,b);int n=Mathf.CeilToInt(length/.16f);for(int i=0;i<=n;i++){float t=(float)i/n;var p=Vector3.Lerp(a,b,t);if(gate&&Mathf.Abs(p.x-988.5f)<1.25f)continue;float y=Y(p.x,p.z);Box("Wire",parent,new(p.x,y+1.8f,p.z),new(.018f,3.6f,.018f),blue,false);}int bays=Mathf.CeilToInt(length/2.8f);for(int i=0;i<=bays;i++){var p=Vector3.Lerp(a,b,(float)i/bays);if(gate&&Mathf.Abs(p.x-988.5f)<1.25f)continue;float y=Y(p.x,p.z);Box("Post",parent,new(p.x,y+1.85f,p.z),new(.07f,3.7f,.07f),blue,false);}for(float y=.2f;y<3.65f;y+=.32f){var pa=a;var pb=b;pa.y=Y(a.x,a.z)+y;pb.y=Y(b.x,b.z)+y;if(!gate)Bar("Horizontal mesh",parent,pa,pb,.015f,blue);else{var ca=Vector3.Lerp(pa,pb,.45f);var cb=Vector3.Lerp(pa,pb,.55f);Bar("Horizontal mesh",parent,pa,ca,.015f,blue);Bar("Horizontal mesh",parent,cb,pb,.015f,blue);}}
  // Thin wall colliders exclude the 2.5m south entrance.
  var delta=b-a;bool horizontal=Mathf.Abs(delta.x)>Mathf.Abs(delta.z);foreach(var interval in gate?new[]{(0f,.445f),(.555f,1f)}:new[]{(0f,1f)}){var mid=Vector3.Lerp(a,b,(interval.Item1+interval.Item2)/2);var g=Group("Fence collision",parent.parent);g.transform.position=Ground(mid.x,mid.z);var c=g.AddComponent<BoxCollider>();c.center=new(0,1.8f,0);c.size=horizontal?new(length*(interval.Item2-interval.Item1),3.6f,.12f):new(.12f,3.6f,length*(interval.Item2-interval.Item1));}}
 static void Playground(){var play=Group("Children playground — slide and swings");Surface("Playground worn soil",887,904,1480,1499,leafFloor,false,.7f,.08f);var tower=Group("Slide tower",play.transform);tower.transform.position=Ground(893,1488);foreach(float x in new[]{-.7f,.7f})foreach(float z in new[]{-.7f,.7f})Box("Tower post",tower.transform,new(x,1.35f,z),new(.10f,2.7f,.10f),yellow);Box("Platform",tower.transform,new(0,1.3f,0),new(1.55f,.12f,1.55f),wood);for(int i=0;i<6;i++)Box("Ladder rung",tower.transform,new(0,.2f+i*.22f,-1.05f),new(.7f,.06f,.08f),blue);Bar("Ladder rail",tower.transform,new(-.45f,0,-1.6f),new(-.45f,1.4f,-.75f),.07f,blue);Bar("Ladder rail",tower.transform,new(.45f,0,-1.6f),new(.45f,1.4f,-.75f),.07f,blue);var slide=Box("Slide chute",tower.transform,new(0,.74f,2.1f),new(.75f,.07f,3),steel);slide.transform.localRotation=Quaternion.Euler(25,0,0);for(int side=-1;side<=1;side+=2)Bar("Chute edge",tower.transform,new(side*.43f,1.55f,.75f),new(side*.43f,.2f,3.45f),.09f,blue);foreach(int side in new[]{-1,1}){var roof=Box("Red pitched roof",tower.transform,new(side*.48f,2.85f,0),new(1.1f,.07f,1.9f),red,false);roof.transform.localRotation=Quaternion.Euler(0,0,side*-30);}
  var swing=Group("Old two seat swings",play.transform);swing.transform.position=Ground(899,1494);foreach(float x in new[]{-2f,2f}){Bar("A frame",swing.transform,new(x,0,-1),new(x,2.5f,0),.10f,blue);Bar("A frame",swing.transform,new(x,0,1),new(x,2.5f,0),.10f,blue);}Bar("Cross bar",swing.transform,new(-2.2f,2.5f,0),new(2.2f,2.5f,0),.1f,blue);foreach(float x in new[]{-.9f,.9f}){Bar("Chain",swing.transform,new(x-.3f,2.5f,0),new(x-.3f,.5f,0),.018f,steel);Bar("Chain",swing.transform,new(x+.3f,2.5f,0),new(x+.3f,.5f,0),.018f,steel);Box("Seat",swing.transform,new(x,.5f,0),new(.72f,.07f,.35f),wood);}
 }
 static void Furniture(){var group=Group("Benches bins and low green rails");foreach(var p in new[]{new Vector3(889,0,1481),new Vector3(902,0,1482),new Vector3(974.5f,0,1481),new Vector3(974.5f,0,1494),new Vector3(902,0,1508),new Vector3(987,0,1507)}){if(!Free(p.x,p.z,1))continue;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Environment/KursHub/Props/Prefabs/KH_Bench.prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.SetParent(group.transform);g.transform.position=Ground(p.x,p.z);g.transform.rotation=Quaternion.Euler(0,p.x>970?90:180,0);var bin=Group("Rusty litter bin",group.transform);bin.transform.position=Ground(p.x+1.5f,p.z);Box("Bin",bin.transform,new(0,.4f,0),new(.4f,.65f,.4f),rust);Box("Opening",bin.transform,new(0,.74f,0),new(.32f,.025f,.32f),steel,false);}
  var rails=Group("Low green garden fences",group.transform);foreach(float z in new[]{1475f,1508f})for(float x=887;x<1001;x+=2.2f){if(!Free(x,z,1)||Walk(x,z)||Rect(x,z,906,969,1460,1502))continue;float y=Y(x,z);Bar("Rail",rails.transform,new(x-1,y+.45f,z),new(x+1,y+.45f,z),.035f,green);foreach(float dx in new[]{-1f,0,1})Bar("Upright",rails.transform,new(x+dx,y,z),new(x+dx,y+.55f,z),.035f,green);}Combine(rails,green,"GreenGardenRails");
 }
}
